// Turns the drift report into a prompt for the local LLM (Ollama).
// report.simulation (the ground-truth scenario) is deliberately NOT sent: the LLM has to
// infer the root cause from the metrics alone, exactly as it would in production.
const r = $input.first().json;
const dd = r.dataset_drift, pd = r.prediction_drift, td = r.target_drift;
const p = r.performance, dq = r.data_quality;
const pct = (v) => (v === null || v === undefined) ? 'n/a' : (v * 100).toFixed(1) + '%';

const top = r.top_drifted_features.map(f =>
  `- ${f.feature}: PSI=${f.psi}, KL=${f.kl_div}, ${f.stattest}=${f.drift_score} (drifted=${f.drifted}), ` +
  `mean ${f.ref_mean} -> ${f.cur_mean} (${f.mean_shift_pct}%), missing=${pct(f.cur_missing_share)}`
).join('\n');
const stable = r.feature_drift.filter(f => !f.drifted && (f.psi ?? 0) < 0.1).map(f => f.feature);
const missing = Object.entries(dq.columns_with_missing || {}).map(([k, v]) => `${k} ${pct(v)}`).join(', ') || 'none';

const system = `You are a senior ML reliability engineer on call for a production classification model.
You receive drift-monitoring metrics computed with Evidently AI and explain them to a busy team in Slack.
Rules:
- Use only the numbers provided. Do not invent metrics.
- Reason about WHICH features moved together and which stayed stable: a coordinated shift in one
  measurement family suggests an instrument or measurement change; a broad shift together with a changed
  label mix suggests a real population change; unit-like jumps (values ~100x off) or missing values
  suggest a data-pipeline bug.
- Say how confident you are.
- Format for Slack mrkdwn (use *bold*, not **bold**; no headings, no tables). Max 170 words.
Structure exactly:
*What changed:* one or two sentences.
*Most likely root cause:* one or two ranked hypotheses, each with the evidence.
*Impact on the model:* one sentence.
*Next steps:* three short bullets.`;

const user = `Model: ${r.model.name} (${r.model.algorithm}), version ${r.model.version}.
Task: predicts whether a breast-mass biopsy is malignant (1) or benign (0).
Inputs: 30 numeric features computed from a digitised biopsy image. Ten measurements (radius, texture,
perimeter, area, smoothness, compactness, concavity, concave points, symmetry, fractal dimension), each as
"mean", "error" (standard error) and "worst" (mean of the three largest values).

Monitoring window: ${r.data.n_current} recent predictions vs. a reference set of ${r.data.n_reference}.
Alert severity: ${r.alert.severity}. Thresholds crossed:
${r.alert.reasons.map(x => '- ' + x).join('\n')}

Dataset-level drift:
- Drifted features (statistical test): ${dd.n_drifted}/${dd.n_features} (${pct(dd.share_drifted)})
- Max PSI: ${dd.max_psi} on "${dd.max_psi_feature}"; mean PSI: ${dd.mean_psi}
- Missing values in current batch: ${missing}
- Target drift (actual malignant rate): ${pct(td.ref_positive_rate)} -> ${pct(td.cur_positive_rate)} (p=${td.p_value}, drifted=${td.detected})
- Prediction drift (predicted malignant rate): ${pct(pd.ref_positive_rate)} -> ${pct(pd.cur_positive_rate)} (PSI=${pd.psi}, drifted=${pd.detected})

Model performance (reference -> current):
- Accuracy ${pct(p.reference.accuracy)} -> ${pct(p.current.accuracy)}; Precision ${p.reference.precision} -> ${p.current.precision}; Recall ${p.reference.recall} -> ${p.current.recall}; ROC AUC ${p.reference.roc_auc} -> ${p.current.roc_auc}

Top features by PSI:
${top}

Stable features (no drift, PSI < 0.1): ${stable.length ? stable.join(', ') : 'none'}

Explain the most likely root cause.`;

const model = $env.OLLAMA_MODEL || 'llama3.1';
return [{
  json: {
    run: r,
    ollama_request: {
      model,
      stream: false,
      // Reasoning models (qwen3, deepseek-r1, ...) would otherwise spend the budget "thinking".
      ...(/qwen3|deepseek-r1|gpt-oss|magistral/i.test(model) ? { think: false } : {}),
      options: { temperature: 0.2, num_predict: 450, num_ctx: 4096 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

// Builds the Slack Block Kit message from the drift report + the LLM explanation.
const run = $('Build root-cause prompt').first().json.run;
const llm = $input.first().json;
const model = $env.OLLAMA_MODEL || 'llama3.1';

let summary = (llm?.message?.content || llm?.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
const llmOk = summary.length > 0;
if (llmOk) {
  summary = summary.replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#+\s*(.+)$/gm, '*$1*');
} else {
  const err = llm?.error?.message || llm?.error || 'no response';
  summary = `_Root-cause summary unavailable: Ollama error (${String(err).slice(0, 200)}). ` +
            `Check that Ollama is running and "${model}" is pulled._`;
}
const clip = (t, n) => t.length > n ? t.slice(0, n - 1) + '…' : t;

const dd = run.dataset_drift, p = run.performance, a = run.alert;
const pct = (v) => (v === null || v === undefined) ? 'n/a' : (v * 100).toFixed(1) + '%';
const icon = a.severity === 'critical' ? ':rotating_light:' : ':warning:';
const top = run.top_drifted_features.slice(0, 5)
  .map(f => `• \`${f.feature}\`  PSI ${f.psi}  ·  mean ${f.mean_shift_pct > 0 ? '+' : ''}${f.mean_shift_pct}%` +
            (f.cur_missing_share ? `  ·  ${pct(f.cur_missing_share)} missing` : ''))
  .join('\n');
const grafanaUrl = ($env.GRAFANA_PUBLIC_URL || 'http://localhost:3000') + '/d/drift-overview';

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `${a.severity === 'critical' ? '🚨' : '⚠️'} Model drift alert: ${a.severity.toUpperCase()}`, emoji: true } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Model*\n${run.model.name}\n\`${run.model.version}\`` },
    { type: 'mrkdwn', text: `*Drifted features*\n${dd.n_drifted}/${dd.n_features} (${pct(dd.share_drifted)})` },
    { type: 'mrkdwn', text: `*Max PSI*\n${dd.max_psi} on \`${dd.max_psi_feature}\`` },
    { type: 'mrkdwn', text: `*Accuracy*\n${pct(p.reference.accuracy)} → ${pct(p.current.accuracy)}` },
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: clip(`${icon} *Why it fired*\n` + a.reasons.map(x => '• ' + x).join('\n'), 2900) } },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: clip(`:robot_face: *Root-cause analysis* (${model}, running locally)\n${summary}`, 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: clip(`*Top drifting features*\n${top}`, 2900) } },
  { type: 'actions', elements: [
    { type: 'button', text: { type: 'plain_text', text: 'Open Evidently report' }, url: run.report_url, style: 'primary' },
    { type: 'button', text: { type: 'plain_text', text: 'Grafana dashboard' }, url: grafanaUrl },
  ] },
  { type: 'context', elements: [
    { type: 'mrkdwn', text: `Run \`${run.run_id}\` · ${run.data.n_current} predictions vs ${run.data.n_reference} reference · links open on the machine running the stack` },
  ] },
];

return [{
  json: {
    run_id: run.run_id,
    llm_ok: llmOk,
    llm_model: model,
    llm_summary: summary,
    slack: { text: `${a.severity.toUpperCase()} model drift alert: ${a.reasons.join('; ')}`, blocks },
  },
}];

// The drift-monitor call itself failed: alert on the pipeline, not on the model.
const item = $input.first().json;
const msg = item?.error?.message || item?.message || JSON.stringify(item).slice(0, 500);
return [{
  json: {
    slack: {
      text: `Drift monitor pipeline failed: ${msg}`,
      blocks: [
        { type: 'header', text: { type: 'plain_text', text: '🛠️ Drift monitor pipeline failed', emoji: true } },
        { type: 'section', text: { type: 'mrkdwn', text: `The scheduled monitoring run could not complete, so drift was *not* checked.\n\`\`\`${String(msg).slice(0, 2500)}\`\`\`` } },
        { type: 'context', elements: [{ type: 'mrkdwn', text: 'Check `docker compose logs drift-monitor` and the n8n execution log.' }] },
      ],
    },
  },
}];
